	@Test
	void addingFixedReferenceAfterOptimizationRefreshesPreflightForOriginalAndClone() throws Exception {
		ValueFactory valueFactory = new LegacyValueFactory("fresh");
		BNode boundSubject = VF.createBNode("external-bound-subject");
		Statement statement = VF.createStatement(boundSubject, PREDICATE, VF.createIRI("urn:o"));
		TripleSource source = new SingleStatementTripleSource(valueFactory, statement);
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT (BNODE() AS ?fresh) WHERE { ?s <urn:p> ?o }", null);
		var bindings = new MapBindingSet();
		bindings.addBinding("s", boundSubject);
		var scope = new BlankNodeAllocationScope("query-mutation-", null);
		try (var activation = scope.activate()) {
			var strategy = new DefaultEvaluationStrategy(source, null);
			TupleExpr optimized = strategy.optimize(parsed.getTupleExpr(), null, bindings);
			assertTrue(hasInlinedSubject(optimized, boundSubject),
					"the external binding must be present before the same optimized root is mutated");

			QueryRoot root = assertInstanceOf(QueryRoot.class, optimized);
			root.setArg(new Extension(root.getArg(),
					new ExtensionElem(new ValueConstant(VF.createBNode("late-local-fixed")), "lateFixed")));
			TupleExpr clone = root.clone();
			assertUnknownBackendRejectsFreshAllocation(strategy, root, bindings);
			assertUnknownBackendRejectsFreshAllocation(strategy, clone, bindings);
		}
	}

	@Test
	void replacingRepeatableValuesRowAfterOptimizationRescansNestedFixedReferences() throws Exception {
		ValueFactory valueFactory = new LegacyValueFactory("fresh");
		BNode boundSubject = VF.createBNode("external-values-subject");
		Statement statement = VF.createStatement(boundSubject, PREDICATE, VF.createIRI("urn:o"));
		TripleSource source = new SingleStatementTripleSource(valueFactory, statement);
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?v (BNODE() AS ?fresh) WHERE { VALUES ?v { <urn:initial> } ?s <urn:p> ?o }", null);
		var bindings = new MapBindingSet();
		bindings.addBinding("s", boundSubject);
		var scope = new BlankNodeAllocationScope("query-values-mutation-", null);
		try (var activation = scope.activate()) {
			var strategy = new DefaultEvaluationStrategy(source, null);
			TupleExpr optimized = strategy.optimize(parsed.getTupleExpr(), null, bindings);
			assertTrue(hasInlinedSubject(optimized, boundSubject),
					"the optimizer must inline the external blank-node binding before the row changes");

			BindingSetAssignment values = valuesAssignment(optimized);
			Value inner = VF.createTripleTerm(VF.createIRI("urn:inner-subject"), PREDICATE,
					VF.createBNode("late-values-nested"));
			Value replacement = VF.createTripleTerm(VF.createIRI("urn:outer-subject"), PREDICATE, inner);
			var row = new MapBindingSet();
			row.addBinding("v", replacement);
			values.setBindingSets(List.of(row));

			assertUnknownBackendRejectsFreshAllocation(strategy, optimized, bindings);
		}
	}

	@Test
	void movingServiceOwnedConstantToLocalQueryRequiresFreshnessValidationAfterOptimization() {
		ValueFactory valueFactory = new LegacyValueFactory("fresh");
		ValueConstant reference = new ValueConstant(VF.createBNode("moved-from-service"));
		var remoteBody = new Extension(new SingletonSet(), new ExtensionElem(reference, "remote"));
		var service = new Service(Var.of("endpoint", VF.createIRI("urn:service")), remoteBody, "", null, null,
				false);
		var root = new QueryRoot(new Extension(service, new ExtensionElem(new BNodeGenerator(), "fresh")));
		var scope = new BlankNodeAllocationScope("query-service-mutation-", null);
		try (var activation = scope.activate()) {
			var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(valueFactory), null);
			TupleExpr optimized = strategy.optimize(root, null, EmptyBindingSet.getInstance());
			assertSame(root, optimized);
			assertTrue(LocalBNodeReferences.collect(root).isEmpty(),
					"the initial fixed identity belongs only to the remote SERVICE");

			service.setArg(new SingletonSet());
			root.setArg(new Extension(root.getArg(), new ExtensionElem(reference, "localFixed")));
			assertTrue(LocalBNodeReferences.collect(root).contains("moved-from-service"),
					"the moved identity is now owned by the local query");

			strategy.precompile(root);
			assertThrows(QueryEvaluationException.class, () -> scope.createBNode(valueFactory),
					"mutating SERVICE ownership after optimization must refresh local fixed-reference admission");
		}
	}

	private static void assertUnknownBackendRejectsFreshAllocation(DefaultEvaluationStrategy strategy,
			TupleExpr expression, BindingSet bindings) {
		assertThrows(QueryEvaluationException.class, () -> {
			try (CloseableIteration<BindingSet> rows = strategy.precompile(expression).evaluate(bindings)) {
				assertTrue(rows.hasNext());
				assertTrue(rows.next().hasBinding("fresh"), "fresh allocation must be evaluated on the row");
			}
		}, "a local fixed reference added after optimization must invalidate the safe factory-only plan");
	}

	private static Extension fixedConstantAndFreshAllocation() {
		return new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(VF.createBNode("fixed")), "fixed"),
				new ExtensionElem(new BNodeGenerator(), "fresh"));
	}

	private static boolean hasInlinedSubject(TupleExpr expression, BNode boundSubject) {
		boolean[] inlined = { false };
		expression.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (pattern.getSubjectVar().hasValue() && boundSubject.equals(pattern.getSubjectVar().getValue())) {
					inlined[0] = true;
				}
				super.meet(pattern);
			}
		});
		return inlined[0];
	}

	private static BindingSetAssignment valuesAssignment(TupleExpr expression) {
		BindingSetAssignment[] assignments = { null };
		expression.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				if (assignments[0] != null) {
					throw new IllegalStateException("expected one VALUES assignment in test query");
				}
				assignments[0] = assignment;
			}
		});
		return assertInstanceOf(BindingSetAssignment.class, assignments[0],
				"the optimized tree must preserve its repeatable VALUES assignment");
	}

	private static final class LegacyValueFactory extends SimpleValueFactory {
		private final String firstId;

		private LegacyValueFactory(String firstId) {
			this.firstId = firstId;
		}

		@Override
		public BNode createBNode() {
			return createBNode(firstId);
		}
	}

	private static final class SingleStatementTripleSource implements TripleSource {
		private final ValueFactory valueFactory;
		private final Statement statement;

		private SingleStatementTripleSource(ValueFactory valueFactory, Statement statement) {
			this.valueFactory = valueFactory;
			this.statement = statement;
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			if ((subject == null || subject.equals(statement.getSubject()))
					&& (predicate == null || predicate.equals(statement.getPredicate()))
					&& (object == null || object.equals(statement.getObject()))) {
				return new SingletonIteration<>(statement);
			}
			return new EmptyIteration<>();
		}
	}
